using InControl;

namespace Game.Input
{
    /// <summary>
    /// InControlを利用したUI操作定義。
    ///
    /// メニューの選択、決定、キャンセル、
    /// タブ切り替えなどの操作を管理する。
    ///
    /// UIそのものの制御は行わず、
    /// 操作の生成と初期キー割り当てのみを担当する。
    /// </summary>
    public sealed class UIActions : PlayerActionSet
    {
        #region Action Properties

        /// <summary>
        /// UIの上方向への選択操作。
        /// </summary>
        public PlayerAction NavigateUp { get; }

        /// <summary>
        /// UIの下方向への選択操作。
        /// </summary>
        public PlayerAction NavigateDown { get; }

        /// <summary>
        /// UIの左方向への選択操作。
        /// </summary>
        public PlayerAction NavigateLeft { get; }

        /// <summary>
        /// UIの右方向への選択操作。
        /// </summary>
        public PlayerAction NavigateRight { get; }

        /// <summary>
        /// 上下左右の選択操作をまとめた2軸入力。
        /// </summary>
        public PlayerTwoAxisAction Navigate { get; }

        /// <summary>
        /// 選択項目の決定操作。
        /// </summary>
        public PlayerAction Submit { get; }

        /// <summary>
        /// 選択のキャンセル操作。
        /// </summary>
        public PlayerAction Cancel { get; }

        /// <summary>
        /// 前のタブへの切り替え操作。
        /// </summary>
        public PlayerAction PreviousTab { get; }

        /// <summary>
        /// 次のタブへの切り替え操作。
        /// </summary>
        public PlayerAction NextTab { get; }

        #endregion

        #region Constructor

        /// <summary>
        /// UI用の操作を生成する。
        ///
        /// このコンストラクタでは操作のみを生成し、
        /// キー割り当ては行わない。
        /// </summary>
        public UIActions()
        {
            // UIの方向選択操作を生成する。
            NavigateUp = CreatePlayerAction(
                nameof(GameInputAction.NavigateUp));

            NavigateDown = CreatePlayerAction(
                nameof(GameInputAction.NavigateDown));

            NavigateLeft = CreatePlayerAction(
                nameof(GameInputAction.NavigateLeft));

            NavigateRight = CreatePlayerAction(
                nameof(GameInputAction.NavigateRight));

            // 4方向の操作を2軸入力にまとめる。
            Navigate = CreateTwoAxisPlayerAction(
                NavigateLeft,
                NavigateRight,
                NavigateDown,
                NavigateUp);

            // 決定・キャンセル操作を生成する。
            Submit = CreatePlayerAction(
                nameof(GameInputAction.Submit));

            Cancel = CreatePlayerAction(
                nameof(GameInputAction.Cancel));

            // タブ切り替え操作を生成する。
            PreviousTab = CreatePlayerAction(
                nameof(GameInputAction.PreviousTab));

            NextTab = CreatePlayerAction(
                nameof(GameInputAction.NextTab));
        }

        #endregion

        #region Factory Methods

        /// <summary>
        /// 初期キー割り当て済みのUI操作セットを生成する。
        /// </summary>
        /// <returns>
        /// 初期キー割り当てが設定された操作セット
        /// </returns>
        public static UIActions CreateWithDefaultBindings()
        {
            // UI用の操作セットを生成する。
            UIActions actions = new UIActions();

            // キーボードの初期割り当てを登録する。
            actions.AddDefaultKeyboardBindings();

            // ゲームパッドの初期割り当てを登録する。
            actions.AddDefaultGamepadBindings();

            return actions;
        }

        #endregion

        #region Default Bindings

        /// <summary>
        /// キーボードの初期キー割り当てを登録する。
        /// </summary>
        private void AddDefaultKeyboardBindings()
        {
            // 上方向への選択。
            NavigateUp.AddDefaultBinding(Key.W);
            NavigateUp.AddDefaultBinding(Key.UpArrow);

            // 下方向への選択。
            NavigateDown.AddDefaultBinding(Key.S);
            NavigateDown.AddDefaultBinding(Key.DownArrow);

            // 左方向への選択。
            NavigateLeft.AddDefaultBinding(Key.A);
            NavigateLeft.AddDefaultBinding(Key.LeftArrow);

            // 右方向への選択。
            NavigateRight.AddDefaultBinding(Key.D);
            NavigateRight.AddDefaultBinding(Key.RightArrow);

            // 選択項目の決定。
            Submit.AddDefaultBinding(Key.Return);
            Submit.AddDefaultBinding(Key.Space);

            // 選択のキャンセル。
            Cancel.AddDefaultBinding(Key.Escape);
            Cancel.AddDefaultBinding(Key.Backspace);

            // 前のタブへの切り替え。
            PreviousTab.AddDefaultBinding(Key.Q);

            // 次のタブへの切り替え。
            NextTab.AddDefaultBinding(Key.E);
        }

        /// <summary>
        /// ゲームパッドの初期ボタン割り当てを登録する。
        /// </summary>
        private void AddDefaultGamepadBindings()
        {
            // 上方向への選択。
            NavigateUp.AddDefaultBinding(
                InputControlType.LeftStickUp);

            NavigateUp.AddDefaultBinding(
                InputControlType.DPadUp);

            // 下方向への選択。
            NavigateDown.AddDefaultBinding(
                InputControlType.LeftStickDown);

            NavigateDown.AddDefaultBinding(
                InputControlType.DPadDown);

            // 左方向への選択。
            NavigateLeft.AddDefaultBinding(
                InputControlType.LeftStickLeft);

            NavigateLeft.AddDefaultBinding(
                InputControlType.DPadLeft);

            // 右方向への選択。
            NavigateRight.AddDefaultBinding(
                InputControlType.LeftStickRight);

            NavigateRight.AddDefaultBinding(
                InputControlType.DPadRight);

            // 選択項目の決定。
            Submit.AddDefaultBinding(
                InputControlType.Action1);

            // 選択のキャンセル。
            Cancel.AddDefaultBinding(
                InputControlType.Action2);

            // 前のタブへの切り替え。
            PreviousTab.AddDefaultBinding(
                InputControlType.LeftBumper);

            // 次のタブへの切り替え。
            NextTab.AddDefaultBinding(
                InputControlType.RightBumper);
        }

        #endregion

        #region Action Lookup Methods

        /// <summary>
        /// 操作識別子に対応する個別操作を取得する。
        ///
        /// 2軸操作のNavigateは個別操作ではないため、
        /// このメソッドでは取得できない。
        /// </summary>
        /// <param name="action">
        /// 取得する操作識別子
        /// </param>
        /// <param name="playerAction">
        /// 取得されたInControlの個別操作
        /// </param>
        /// <returns>
        /// 対応する操作が存在する場合はtrue
        /// </returns>
        public bool TryGetPlayerAction(
            GameInputAction action,
            out PlayerAction playerAction)
        {
            switch (action)
            {
                case GameInputAction.NavigateUp:
                    playerAction = NavigateUp;
                    return true;

                case GameInputAction.NavigateDown:
                    playerAction = NavigateDown;
                    return true;

                case GameInputAction.NavigateLeft:
                    playerAction = NavigateLeft;
                    return true;

                case GameInputAction.NavigateRight:
                    playerAction = NavigateRight;
                    return true;

                case GameInputAction.Submit:
                    playerAction = Submit;
                    return true;

                case GameInputAction.Cancel:
                    playerAction = Cancel;
                    return true;

                case GameInputAction.PreviousTab:
                    playerAction = PreviousTab;
                    return true;

                case GameInputAction.NextTab:
                    playerAction = NextTab;
                    return true;

                default:
                    playerAction = null;
                    return false;
            }
        }

        /// <summary>
        /// 操作識別子に対応する2軸操作を取得する。
        /// </summary>
        /// <param name="action">
        /// 取得する操作識別子
        /// </param>
        /// <param name="axisAction">
        /// 取得されたInControlの2軸操作
        /// </param>
        /// <returns>
        /// 対応する2軸操作が存在する場合はtrue
        /// </returns>
        public bool TryGetTwoAxisAction(
            GameInputAction action,
            out PlayerTwoAxisAction axisAction)
        {
            if (action == GameInputAction.Navigate)
            {
                axisAction = Navigate;
                return true;
            }

            axisAction = null;
            return false;
        }

        /// <summary>
        /// 指定された操作が登録されているか確認する。
        /// </summary>
        /// <param name="action">
        /// 確認する操作識別子
        /// </param>
        /// <returns>
        /// 操作が登録されている場合はtrue
        /// </returns>
        public bool HasAction(GameInputAction action)
        {
            return TryGetPlayerAction(action, out _) ||
                   TryGetTwoAxisAction(action, out _);
        }

        #endregion
    }
}
